import{_ as a,o as n,c as e,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"What Does a Temporal Benchmark Score Measure? Decomposing Channel Use in Video VLM Evaluation","description":"","frontmatter":{"title":"What Does a Temporal Benchmark Score Measure? Decomposing Channel Use in Video VLM Evaluation","arxiv":"2607.12304","date":"2026-07-14","authors":"Farrukh Rahman","categories":"cs.CV, cs.LG","topics":"长视频理解, 时序诊断, 位置编码","outline":[2,2]},"headers":[],"relativePath":"papers/2607.12304.md","filePath":"papers/2607.12304.md","lastUpdated":null}'),p={name:"papers/2607.12304.md"};function r(l,s,m,o,i,c){return n(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="what-does-a-temporal-benchmark-score-measure-decomposing-channel-use-in-video-vlm-evaluation" tabindex="-1">What Does a Temporal Benchmark Score Measure? Decomposing Channel Use in Video VLM Evaluation <a class="header-anchor" href="#what-does-a-temporal-benchmark-score-measure-decomposing-channel-use-in-video-vlm-evaluation" aria-label="Permalink to &quot;What Does a Temporal Benchmark Score Measure? Decomposing Channel Use in Video VLM Evaluation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.12304" target="_blank" rel="noreferrer">2607.12304</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-14</td></tr><tr><td><strong>作者</strong></td><td>Farrukh Rahman</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.LG（9 页正文 + 11 页补充）</td></tr><tr><td><strong>一句话</strong></td><td>把画面倒过来播、同时把 RoPE 位置索引钉在正向，制造像素与位置的直接冲突：Molmo2 按位置作答（reversal-drop 近零），Qwen3-VL 按看到的画面作答（每个时序任务掉 0.24–0.55），两者基准总分却一样，说明一个时序分数看不出模型用的是哪条通道。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/html/2607.12304v1</code> 全文撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>一个时序视频问答的分数被默认解读成&quot;模型理解了时间&quot;。作者指出这句话混了两个问题。<strong>任务问题</strong>：这道题本身需不需要多帧、需不需要它们的顺序？<strong>通道问题</strong>：当它确实需要顺序时，模型是从像素里恢复顺序，还是从位置编码（RoPE）里读出来的？</p><p>领域现有的两个有效性检查——帧打乱敏感性与完整视频相对单帧的增益——只回答第一个问题。它们能告诉你&quot;聚合的时序信号非零&quot;，但告诉不了你这个信号由哪条通道承载。</p><p>为什么这件事重要，作者给了一个非常锋利的例子。Molmo2 与 Qwen3-VL 在 TempCompass 上有相近的基准分，两者的 multi-frame gain 都是大约 +0.20，也就是说按现有审计标准它们&quot;同样时序&quot;。但把像素倒放而 RoPE 保持正向时，Molmo2 回答的是<strong>正向</strong>事件（读位置），Qwen3-VL 回答的是<strong>反向</strong>事件（读像素）。两个通道在相反的输入上失效，因此两个分数相近的模型并不可互换，聚合分数反映不出它们各自的失效模式。</p><p>对做长视频研究的人来说，这条结论的直接后果是：跨基座的时序结论几乎不可迁移。在 Qwen 上验证有效的时序改进，在 Molmo 上可能因为模型根本不从像素读顺序而完全失效。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>捷径学习的传统</strong>：视觉问答里模型学会了利用语言先验与数据集偏差；图像分类器依赖纹理而非形状；许多动作识别任务被证明单帧可解，或者打乱帧序后成绩基本不变。作者把自己接在这条脉络上，并指出这条脉络产生的两个常规诊断（帧打乱敏感性、多帧增益）都只覆盖任务问题。</p><p><strong>抗捷径的基准</strong>：TempCompass 引入多样的时序侧面与冲突式视频；TVBench 重建视频 VQA 以抵抗单帧与帧打乱捷径；VBenchComp（本页另一篇解读，arXiv:2505.14321）把题目分成语言可答、打乱鲁棒与时序三类。作者的批评不是这些基准做得不好，而是它们的判据在设计上就只针对任务问题——一道题即便通过了&quot;必须多帧且必须有序&quot;的检验，它仍然没有约束模型用哪条通道来获得这个顺序。</p><p><strong>机制侧的相关工作</strong>：作者提到已有工作对因果模型给出了兼容的结论，但强调这个行为并非普适——Molmo2 对视觉 token 用双向注意力，强烈位置主导，在视觉序列被反转时跟随位置编码。这一点是本文相对既有机制解释的增量。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是一个观察：视频 VLM 同时通过几条通道接收时间信息——像素（帧间运动）、上下文里的时间戳文本、以及旋转位置编码。基准分数把它们聚合起来，权重取决于输入与模型。打乱敏感性告诉你聚合信号非零，但不告诉你权重分布。</p><p>第一步是验证这个担忧不是空想。只扰乱 RoPE 而保持像素完好（rop-shuf），看代价有多大。结果：这对 Molmo 的代价与整体像素打乱差不多（相差不到 2 个点），比基线低 14 到 18 个点，说明 RoPE 是它的主要顺序载体；同样的操作对 Qwen 只花 3 到 7 个点。两个模型的打乱敏感性相近，依赖的通道却不同。</p><p>第二步是设计能把两条通道分开的输入。打乱是同时破坏两条，没有分辨力。反转则不同：把帧倒着放，同时把每帧的 RoPE 位置重置回原来的正向索引，像素说&quot;从蓝到粉&quot;、位置说&quot;从粉到蓝&quot;。读位置的模型答正向、准确率保持；读像素的模型答反向、准确率崩塌。这就是 rev-corr。</p><p>第四步是排除&quot;冲突构造本身制造了这个分裂&quot;。用残差流的 activation patching：把正序运行时的干净视觉 token 状态记录下来，插进打乱运行的指定层，看能恢复多少。恢复位置的差异揭示了架构差异，这把行为分裂锚定成内部属性。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>打乱帧序会同时破坏像素顺序和位置顺序，所以它只能告诉你&quot;顺序有用&quot;。要知道模型从哪读顺序，就得让两者<strong>打架</strong>：像素倒放、位置保持正向。跟着位置走的模型答案不变，跟着像素走的模型答案翻转。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>模型</strong>（三个家族，跨两种注意力架构与两种位置编码）。Qwen3-VL（4B、8B）：全程因果注意力；视觉 token 用 3D MRoPE，时间索引被复制为 H/W 轴的基，因此时序被冗余编码在三条轴上；DeepStack 把中间 ViT 特征注入 LLM 的 0–2 层。Molmo2（4B、8B、O-7B）：1D 顺序 RoPE，视觉 token 用双向注意力（通过 <code>token_type_ids</code>），文本用因果注意力，prefill 阶段帧间信息流只受 RoPE 约束而不受顺序掩码约束。PerceptionLM（1B、3B）：1D 顺序 RoPE，全因果，无文本时间戳格式。行为干预跑全部七个模型，线性探针只跑 Qwen3-VL 与 Molmo2。</p><p><strong>基准</strong>。TempCompass：410 段视频、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1580</span></span></span></span> 道多选，五个侧面（action、attribute_change、direction、order、speed），其中 action 与 speed 不用于逐侧面的顺序分析。TVBench：2205 道多选、九个类别，用宏平均准确率；无配对反转视频，反转直接作用在原片。</p><p><strong>信息阶梯</strong>（量化任务问题）。三档：blank（全零像素，只剩答案先验与选项泄漏）、single-frame（第 0 帧重复，保留其时间戳）、完整视频。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">multi-frame gain</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">acc(full)</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">acc(single-frame)</span></span></span></span></span>；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">order-gain</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">acc(full)</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">acc(shuffled)</span></span></span></span></span>。作者说明配对标准误约 0.03，因此把低于 0.05 的增益视为零。单帧条件保留时间戳，因为剥掉时间戳的孤帧对某些模型是分布外的。一道题对某模型是 <strong>motion-dependent</strong> 的，当且仅当它在完整视频下答对、在单帧下答错。</p><p><strong>干预协议</strong>（三条通道各自独立操纵）。视觉顺序：normal / single-frame / shuffled（每视频固定）/ reversed / blank；作者在补充 C 里验证了 Conv3d 嵌入之后再打乱与之前打乱结果等价，排除 Conv3d 作为独立时序通道。时间戳：present / absent / mismatched / reversed。位置编码：native（匹配输入顺序）/ corrected（不管输入顺序都跟随原始帧索引，打乱下第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 槽拿第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span></span></span></span> 帧的位置）/ shuffled 或 reversed。另有 rop-shuf、rop-rev 这类&quot;像素正确、RoPE 错误&quot;的条件用于隔离 RoPE 效应。冲突条件包括 conf-ts（正向画面 + 反向时间戳）、rev-mvts（画面与时间戳一致反转）、conf-ts2、rev-corr（反转画面 + 校正 RoPE）。</p><p><strong>打分方式</strong>。TempCompass 有 95 对配对视频（<code>{id}</code> 与 <code>{id}_reverse</code>），attribute_change 144 对、direction 157 对带独立调整过的真值。在原始视频的 rev-corr 条件下，把预测同时对照原内容真值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 与反转内容真值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span> 打分，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 表示模型把反转内容读成了正向时间，即 position-dominant。TVBench 没有配对，则用 reversal-drop 当免标注筛子。</p><p><strong>Activation patching</strong>。记录正序 base 运行的视觉 token 状态，插入 shuf 运行的选定层。利用原帧对应关系：shuf 运行第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 槽装的是第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span></span></span></span> 帧，于是把 base 中第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span></span></span></span> 槽的激活装到第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 槽，使每个被 patch 的视觉 token 携带它在未打乱运行中本应有的激活。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。核心的三个量都是准确率差：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">multi-frame gain</span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">order-gain</span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">reversal-drop</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">acc(base)</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">acc(rev-corr)</span></span></span></span></span>，以及配对打分下的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span>。</p><p>值得单独说明的是这三个量的逻辑关系，因为它们构成了一个筛子的三级。multi-frame gain 为正只说明需要多帧，不说明需要顺序——speed 侧面就是干净的反例（gain +0.11，order-gain 只有 0.03–0.05）。order-gain 为正说明需要顺序，但不说明顺序从哪来。reversal-drop 才回答通道问题。三者互不蕴含，所以必须分开报。</p><p>作者还点出 order-gain 顺带修掉了一个混淆：order 侧面在单帧基线下看起来只是弱运动依赖，因为它的单帧基线用的是第 0 帧，而第 0 帧泄漏了哪个事件在前；打乱基线不泄漏这个信息，所以 order-gain 直接测顺序依赖。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：一个时序分数里有多少是时序的？</strong> 表 2 按 TempCompass 侧面给两族模型的分解（族内平均）。multi-frame gain / order-gain：attribute_change Molmo +0.46/+0.37、Qwen +0.52/+0.35；order Molmo +0.29/+0.32、Qwen +0.21/+0.37；direction Molmo +0.17/+0.14、Qwen +0.19/+0.12；speed Molmo +0.11/+0.05、Qwen +0.11/+0.03；action Molmo +0.09/+0.01、Qwen +0.05/+0.00；Overall Molmo +0.22/+0.17、Qwen +0.21/+0.17。作者点名 action 是近饱和但几乎不用像素的例子——它在全黑帧下的盲答准确率已经约 0.5，而随机水平是 0.29，说明分数来自单帧识别与答案先验泄漏。speed 是干净的分离器：需要多帧但不需要顺序。</p><p><strong>问题二：打乱敏感性能识别通道吗？</strong> 不能。rop-shuf（只打乱 RoPE、像素完好）对 Molmo 的代价与整体像素打乱相差不到 2 个点、比基线低 14–18 个点；对 Qwen 只花 3–7 个点，与其 3D MRoPE 把顺序冗余编码在多轴上一致。两个模型的打乱敏感性接近，依赖的通道不同。</p><p><strong>问题三：通道分裂长什么样？</strong> 表 3 给 TVBench 上逐任务的 reversal-drop（Molmo 4B / Molmo 8B / Qwen 4B / Qwen 8B）：scene_transition +0.01 / +0.00 / <strong>+0.55</strong> / <strong>+0.55</strong>；moving_direction +0.08 / +0.02 / +0.41 / +0.33；action_sequence +0.00 / +0.01 / +0.36 / +0.33；action_localization +0.02 / +0.06 / +0.29 / +0.29；egocentric_sequence −0.01 / +0.14 / +0.24 / +0.23；object_count +0.01 / +0.03 / +0.18 / +0.10；unexpected_action +0.04 / +0.06 / +0.11 / +0.14；action_count 全部 ≤ +0.08；非时序的 object_shuffle 四列都在 −0.06 到 −0.01。Molmo 的时序任务平均掉幅 +0.04、最大 +0.14；Qwen 在每个时序任务上都崩。两者在这些任务上的 base 准确率都很高，所以都在用画面内容，差别只在如何绑定顺序。</p><p>表 4 用 TempCompass 的配对真值量化同一分裂（attribute_change）。base / rev-corr / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span>（motion-dependent 切片）：Molmo2 4B 0.965 / 0.965 / −0.957 / −1.000；Molmo2 8B 0.972 / 0.965 / −0.950 / −0.983；Molmo2 O-7B 0.965 / 0.882 / −0.816 / −0.766；Qwen3-VL 4B 0.944 / 0.576 / −0.234 / +0.014；Qwen3-VL 8B 0.972 / 0.549 / −0.135 / +0.237。两族的 base 分数几乎相同（0.944–0.972），在 rev-corr 下劈开。<strong>§7 的核心数字来自表 3（TVBench reversal-drop 逐任务）与表 4（TempCompass 配对真值，base / rev-corr / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 三列）。</strong></p><p>作者还排除了一个自然的疑虑：Molmo 的覆盖是不是骑在单帧就能答的题上？不是。限制到 motion-dependent 切片后，Molmo 的覆盖同样强或更强（attribute_change 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 接近 −1.0），而 Qwen 的覆盖只出现在静态题上，在需要运动的地方消失（4B 与 8B 都是）。镜像冲突（正向画面 + 反向 RoPE）翻转了这个模式，Molmo 失败而 Qwen 成功。</p><p><strong>问题四：这个分裂是网络内部的属性吗？</strong> 输入端的 RoPE 校正（shuf-corr）能把 Molmo 恢复到接近基线，但在因果模型 Qwen 与 PLM 上留下残差（表 5）。作者的解释与注意力掩码的预测一致：因果注意力下 K/V 在 prefill 阶段就已经承诺了打乱后的邻居上下文，之后再改 RoPE 无法重组；双向注意力让 Molmo 可以对照校正后的位置重新整合。Patching 直接检验了这一点：在 LM 第 0 层安装校正内容能完全恢复 Molmo（表 6 注明三个规模上 act gap 均为 0.000），Qwen 的残差要到 0–2 层才闭合，正是 DeepStack 的注入深度。</p><p><strong>规模趋势</strong>：Qwen 的覆盖随规模减弱（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 从 4B 的 −0.234 到 8B 的 −0.135，motion-dependent 切片从 +0.014 到 +0.237），Molmo 在两个规模上都饱和。PerceptionLM 填在中间——1D 位置编码像 Molmo、因果注意力像 Qwen，在 attribute_change 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.5</span></span></span></span>。作者据此说 Molmo2 &gt; PLM &gt; Qwen3-VL 的排序与&quot;1D 位置编码与双向注意力都把模型推向读位置&quot;一致，因此两个因素都不能单独解释这个分裂。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：帧打乱同时破坏像素顺序与位置顺序，因此只能证明&quot;顺序有用&quot;，不能说明模型从哪读顺序。把画面倒放而 RoPE 保持正向，就把两条通道推进直接冲突，reversal-drop 因此成为一个免标注、可挂在任何兼容时序基准上的筛子。Molmo2 在 TVBench 的时序任务上平均只掉 +0.04，Qwen3-VL 每个任务都掉 0.24–0.55，而两者的 base 准确率与 multi-frame gain（都约 +0.20）几乎一样。TempCompass 的配对真值给出同向证据：Molmo 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 接近 −0.95，Qwen 只有 −0.13 到 −0.23，且在 motion-dependent 切片上翻正。Activation patching 把这个分裂锚定到架构上——Molmo 在 LM 第 0 层就能完全恢复，Qwen 要到 0–2 层（DeepStack 注入深度）才闭合。</p><p><strong>3 句版</strong>：一个时序分数混了三件事：要不要多帧、要不要顺序、顺序从哪来。前两件由 multi-frame gain 与 shuffle sensitivity 回答，第三件必须靠反转冲突。两个分数相近的模型可以在相反的输入上失效，所以聚合分数不支持机制层面的比较。</p><p><strong>1 句版</strong>：跨基座的时序结论不可迁移，因为不同基座读的是不同的通道。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>&quot;corrected RoPE&quot; 在不同架构上是同等保真的干预</strong>。表 3、表 4 的整个对比是把 Molmo 与 Qwen 放在同一个 rev-corr 条件下比较，这要求这个条件在两边施加的是同一件事。</p><p>它在两个架构上并不是同一件事，而作者自己的补充材料给出了证据。Molmo2 用 1D 顺序 RoPE，把每个视觉 token 的位置索引改回原值是一个完整、无歧义的操作。Qwen3-VL 用 3D MRoPE，时间基被复制到 H/W 两条轴上，所以&quot;校正&quot;必须同时改三条轴；补充 D 的轴向消融（表 8）明确报告恢复程度随被校正的轴数递增，也就是说校正是<strong>分级的</strong>而不是二值的。更麻烦的是 DeepStack：它在 LM 的 0–2 层内部注入中间 ViT 特征，而这些特征在前向过程中重新引入了未经校正的顺序信息。作者在补充 C 里量化了这个再污染，Qwen 的差距是 −0.016/−0.015，约 1 个百分点。</p><p>问题在于这条不对称与结论的方向是同向的。若 Qwen 的 RoPE 校正天然不如 Molmo 彻底，那么 Qwen 在 rev-corr 下崩塌就有一个不涉及&quot;通道偏好&quot;的替代解释：它接收到的其实是一个<strong>内部自相矛盾</strong>的输入（部分校正的位置 + 未校正的 DeepStack 特征 + 反转的像素），崩的是一致性而不是通道。表 3 里 Qwen 在非时序的 object_shuffle 上掉幅为 −0.05 到 −0.01，说明这种&quot;纯混乱代价&quot;不大，但 object_shuffle 的基线难度与时序任务不同，不能直接外推。</p><p>论文为这条假设提供的证据是相当扎实的，需要如实说明：轴向消融（表 8）显示恢复随校正轴数单调上升，说明校正机制本身有效；补充 C 用 emb-shuf 证明像素级打乱与嵌入后打乱等价，排除了 Conv3d 作为独立通道；patching 显示 Qwen 的残差恰好在 DeepStack 注入深度闭合，把不完整性定位到了一个具体机制而不是留作未知。这些让替代解释变得不太可能，但没有把它排除到零——真正能排除它的对照是把 DeepStack 关掉再重跑 rev-corr（作者在补充 E 里做了 DeepStack 消融，结论是它不提供超出 RoPE 的独立时序信号，但正文没有报告&quot;关掉 DeepStack 后的 reversal-drop&quot;这个具体数字）。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要七个模型两个基准。取 TVBench 的两个时序任务（scene_transition 与 action_sequence，分裂最大）与两个模型（Qwen3-VL-4B 与 Molmo2-4B），一周可完成：</p><ol><li>实现三个条件：base、rev（反转像素、RoPE 用 native 即也跟着反转）、rev-corr（反转像素、RoPE 校正回正向）。第二个条件是论文正文没有单独报数的关键对照。</li><li>计算两个量：论文的 reversal-drop = acc(base) − acc(rev-corr)，以及<strong>一致反转下的掉幅</strong> = acc(base) − acc(rev)。</li><li>判据：若 Qwen 在 rev-corr 下掉 0.55 而在一致反转 rev 下只掉 0.1，那么它的崩塌确实由冲突引起，通道解释成立；若两者掉幅接近，说明 Qwen 只是对&quot;倒放的像素&quot;本身敏感（倒放视频在物理上是分布外的），冲突并非必要条件，reversal-drop 测的是倒放鲁棒性而不是通道偏好。</li><li>附加对照：对 Molmo 做同样的两个量。如果 Molmo 在一致反转下也几乎不掉，那它就不是&quot;读位置&quot;，而是根本不读顺序，表 4 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.95</span></span></span></span> 需要重新解读。</li><li>用 Wilson 区间报告所有比例。TVBench 单任务的题量在两三百量级，0.05 以内的差异不可解释。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击针对 TVBench 那张表的可解释性，而攻击的武器是作者自己写在 §5.3 &quot;Scope of the reversal-drop&quot; 里的一句话：<strong>免标注形式的 reversal-drop 是一个筛子而不是分类器；掉幅可能反映跟随了反转事件，也可能只是被冲突搞糊涂了</strong>。作者提供的区分手段是配对反转标签，或 moving_direction 这类反转后标签确定翻转的任务。</p><p>问题在于全文最广的那条主张——&quot;Qwen 在<strong>每一个</strong>时序任务上都崩&quot;——正是建立在 TVBench 上，而 TVBench 没有配对标签。九个任务里只有 moving_direction 一个具备确定性反转标签，其余四个时序任务（scene_transition、action_sequence、action_localization、egocentric_sequence）的掉幅无法区分&quot;跟随反转&quot;与&quot;被冲突击溃&quot;。而恰恰是掉幅最大的 scene_transition（+0.55，四个模型列中的最高值）没有任何配对检查。</p><p>构造反例的方式是补齐两条对照。第一条是 §10 里的一致反转 rev：如果 Qwen 在 rev（像素与位置一起反转，内部自洽、无冲突）上也掉 0.4 以上，那么 rev-corr 的 0.55 里绝大部分与冲突无关，&quot;visual-sequence-dominant&quot; 这个标签在 TVBench 上没有支撑。论文在 §3.5 定义了 rev-mvts 这个一致反转条件，但正文没有报告它在 TVBench 上的数值，这是一个可以被直接补上的空缺。第二条是给 scene_transition 人工标注 200 条反转真值（这类任务的反转标签其实是机械可推的：转场顺序反过来），然后在 rev-corr 下双向打分，看 Qwen 的错误是不是集中在反转真值上。若不是，它就是被打懵了。</p><p>第二重攻击针对架构归因。作者已经诚实地写在 limitations 里：架构归因受限于可得的开源模型，PerceptionLM 排除了&quot;单靠注意力类型&quot;或&quot;单靠位置编码&quot;的解释，但双向注意力这一侧只有 Molmo2 一个样本，而这三个家族的训练数据也不同。这意味着 Molmo2 &gt; PLM &gt; Qwen3-VL 这个排序有一个完全等价的替代解释：Molmo2 的训练数据里时间戳与位置线索比像素运动更可靠，因此模型学会了优先读位置，与注意力是否双向无关。要区分这两个解释，需要控制变量的实验——同一份数据、同一个规模，只切换视觉 token 的注意力掩码，训两个模型。这在学术预算内不容易做，但在结论表述上应当把&quot;architecture-specific property&quot;降格为&quot;与架构相关且与训练数据混淆&quot;。</p><p>第三点是覆盖面。整项研究只跑了两个<strong>短视频</strong> VQA 基准（TempCompass 410 段、TVBench 2205 题），作者自己指出这一点并把长视频留给未来工作。这限制得比看起来更严重：RoPE 与像素之间的权重分配很可能随序列长度变化——长视频里位置索引跨度大得多、像素冗余也高得多。因此 &quot;Molmo 是 position-dominant&quot; 这个结论能否外推到长视频，目前是零证据。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动这个 idea 的局限是 reversal-drop 的二值性：它把模型贴上 position-dominant 或 visual-sequence-dominant 的标签，而作者自己强调这不是两种模式而是一个连续的 regime，PerceptionLM 正好落在中间（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.5</span></span></span></span>）。一个只有&quot;筛子&quot;没有&quot;刻度&quot;的诊断，无法回答&quot;我的训练改动把通道权重推动了多少&quot;这个开发者真正关心的问题。</p><p>值得借鉴的相邻工具来自心理物理学的<strong>线索冲突范式</strong>：不要只做一次全反转，而是把两条通道的冲突程度连续参数化，测出一条心理测量曲线，从曲线的拐点读出权重。具体做法是构造一族部分冲突条件——只把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个帧对调位置索引而其余保持一致，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 从 0 扫到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span>；或者把 RoPE 的间距按因子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 拉伸（作者已经实现了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord">Δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.25</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">8</span><span class="mclose">}</span></span></span></span> 的间距 warp，但用它测的是播放速率而不是通道权重）。对每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 记录模型答&quot;正向事件&quot;的比例，拟合出的 50% 交叉点就是这个模型在该任务上的通道权重估计，量纲统一、可跨模型跨任务比较。</p><p>第一个实验不需要新模型也不需要新标注：在 TempCompass 的 attribute_change 配对子集（144 对，有双向真值）上，对 Molmo2-4B、PerceptionLM-3B、Qwen3-VL-4B 三个模型扫 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，画出三条曲线。若三条曲线是同一形状的平移（拐点不同、斜率相同），说明通道权重确实是一个单一的标量属性，可以作为模型卡上的一个报告项；若曲线形状差异很大（例如 Molmo 是阶跃、Qwen 是缓坡），说明两族模型的通道整合机制在结构上就不同，&quot;权重&quot;这个比喻本身失效，那么下一步该做的是分别刻画各自的整合规则，而不是继续找一个统一的标量。</p>',61)])])}const d=a(p,[["render",r]]);export{g as __pageData,d as default};
